public import AemiProtobuf

/// The record as a protobuf message, generated by `@ProtoMessage`: `id = 1`, `login = 2`, `optional name = 3`,
/// `optional email = 4`, `followers = 5`, `following = 6`, `is_admin = 7`, `score = 8` (double), `repeated tags = 9`,
/// `profile = 10`.
@ProtoMessage
public struct ProtoUser: Equatable {
    @ProtoField(1) public var id: Int64 = 0
    @ProtoField(2) public var login: String = ""
    @ProtoField(3) public var name: String? = nil
    @ProtoField(4) public var email: String? = nil
    @ProtoField(5) public var followers: Int64 = 0
    @ProtoField(6) public var following: Int64 = 0
    @ProtoField(7) public var isAdmin: Bool = false
    @ProtoField(8) public var score: Double = 0
    @ProtoField(9) public var tags: [String] = []
    @ProtoField(10) public var profile: ProtoProfile = ProtoProfile()
}

extension ProtoUser {
    public init(_ r: Record) {
        self.init(
            id: Int64(r.id), login: r.login, name: r.name, email: r.email, followers: Int64(r.followers),
            following: Int64(r.following), isAdmin: r.isAdmin, score: r.score, tags: r.tags,
            profile: ProtoProfile(
                bio: r.bio, company: r.company, publicRepos: Int64(r.publicRepos), location: r.location))
    }

    public var record: Record {
        Record(
            id: Int(id), login: login, name: name, email: email, followers: Int(followers), following: Int(following),
            isAdmin: isAdmin, score: score, tags: tags, bio: profile.bio, company: profile.company,
            publicRepos: Int(profile.publicRepos), location: profile.location)
    }
}
